class Solution {
  public int[][] sortMatrix(int[][] grid) {
    int n = grid.length;
    for (int d = -(n - 1); d <= n - 1; d++) { // d = row - col
      List<Integer> values = new ArrayList<>();
      for (int i = Math.max(d, 0); i < n && i - d < n; i++) values.add(grid[i][i - d]);
      Collections.sort(values);
      if (d >= 0) Collections.reverse(values); // bottom-left (and main) diagonals: non-increasing
      int k = 0;
      for (int i = Math.max(d, 0); i < n && i - d < n; i++) grid[i][i - d] = values.get(k++);
    }
    return grid;
  }
}
